    /**
     * Theme records in ThemeLibrary::all() format.
     *
     * @return list<array<string, mixed>>
     */
    public static function all(): array
    {
        return array_map(function (array $d) {
            [$heading, $body] = $d['fonts'];

            return [
                'name' => $d['name'],
                'slug' => Str::slug($d['name']),
                'category' => $d['category'],
                'description' => "{$d['name']}: a premium portrait card with a softly lit photo-style front, an icon band, and a QR back with a \"Scan for\" action row. Replace the scene with your own photo any time.",
                'palette' => $d['palette'],
                'fonts' => ['heading' => $heading, 'body' => $body],
                'front' => self::front($d),
                'back' => self::back($d),
                'layout' => [
                    'archetype' => 'premium-portrait', 'bleed_mm' => 3, 'safe_mm' => 3, 'corner_radius_mm' => 3,
                    // Sample business shown in previews (and in designs with no customer yet).
                    'sample' => $d['sample'] + ['logo' => self::ART.$d['key'].'/emblem.svg'],
                ],
                'width_mm' => self::W,
                'height_mm' => self::H,
                'orientation' => 'portrait',
                'is_premium' => true,
            ];
        }, self::definitions());
    }

    // ------------------------------------------------------------------ sides

    private static function front(array $d): array
    {
        [$heading, $body] = $d['fonts'];
        $cx = self::W / 2;

        $elements = [
            self::image('front-logo', $cx - 12, 3.5, 24, 18),
            self::text('front-company', '{{company}}', 2, 21.5, self::W - 4, $d['size'], $heading, $d['weight'], 'palette.text', ['name' => 'Business name', 'letterSpacing' => $d['tracking'] ?? 0]),
            ...self::subtitle('front', $d['subtitle'], 31.4, $body),
            self::text('front-tagline', '{{tagline}}', 3, 35.6, self::W - 6, 10, $heading === 'Bebas Neue' ? $body : $heading, $heading === 'Bebas Neue' ? 500 : $d['weight'], 'palette.text', ['name' => 'Tagline', 'fontSize' => $heading === 'Bebas Neue' ? 7 : ($d['taglineSize'] ?? 10)]),

            self::shape('front-band', -3, 70, self::W + 6, self::H - 70 + 3, 'palette.primary', name: 'Icon band', opacity: 0.94),
            self::line('front-band-line', -3, 69.5, self::W + 6, 'palette.accent', 0.35, name: 'Band edge'),
        ];

        foreach ($d['front'] as $i => [$icon, $label]) {
            $x = 7.5 + 13 * $i;
            $elements[] = self::icon("front-icon-$i", $icon, $x - 2.8, 72.2, 5.6, 'palette.accent', 1.6, $label.' icon');
            $elements[] = self::text("front-label-$i", $label, $x - 6.5, 78.6, 13, 5, $body, 600, 'palette.text', ['name' => $label.' label', 'textTransform' => 'uppercase', 'letterSpacing' => 60]);
            if ($i > 0) {
                $elements[] = self::vline("front-sep-$i", 14 + 13 * ($i - 1), 72.4, 9.6, 'palette.accent', 0.2);
            }
        }

        return [
            'background' => ['type' => 'image', 'src' => self::ART.$d['key'].'/front.svg', 'fit' => 'cover', 'color' => $d['palette']['primary']],
            'elements' => $elements,
        ];
    }

    private static function back(array $d): array
    {
        [$heading, $body] = $d['fonts'];
        $cx = self::W / 2;

        $elements = [];
        $spots = [[2.5, 3.5, 7, -20], [45, 4, 6.5, 25], [2, 38, 6, -15], [46.5, 40, 5.5, 20], [3, 52, 5, 12], [45.5, 53, 5.5, -25]];
        foreach ($spots as $i => [$x, $y, $size, $rot]) {
            $el = self::icon("back-decor-$i", $d['decor'][$i % count($d['decor'])], $x, $y, $size, 'palette.accent', 1.1, 'Decoration');
            $elements[] = array_merge($el, ['rotation' => $rot, 'opacity' => 0.45]);
        }

        $elements = [
            ...$elements,
            self::image('back-logo', $cx - 9, 4, 18, 13.5),
            self::text('back-company', '{{company}}', 2, 17.6, self::W - 4, round($d['size'] * 0.8, 1), $heading, $d['weight'], 'palette.text', ['name' => 'Business name', 'letterSpacing' => $d['tracking'] ?? 0]),
            ...self::subtitle('back', $d['subtitle'], 26.2, $body),
            self::text('back-tagline', '{{tagline}}', 3, 29.8, self::W - 6, 9, $heading === 'Bebas Neue' ? $body : $heading, $heading === 'Bebas Neue' ? 500 : $d['weight'], 'palette.text', ['name' => 'Tagline', 'fontSize' => $heading === 'Bebas Neue' ? 6.5 : round(($d['taglineSize'] ?? 10) * 0.9, 1)]),

            self::shape('back-qr-frame', $cx - 12.5, 35, 25, 25, '#ffffff', stroke: 'palette.accent', strokeWidth: 0.7, radius: 2.4, name: 'QR frame'),
            self::qr('back-qr', $cx - 10.5, 37, 21),

            self::line('back-scan-left', 5, 62.3, 13, 'palette.accent', 0.25, name: 'Scan line'),
            self::text('back-scan', 'Scan for', 18, 61.6, 18, 5.6, $body, 600, 'palette.text', ['name' => 'Scan for', 'textTransform' => 'uppercase', 'letterSpacing' => 260]),
            self::line('back-scan-right', 36, 62.3, 13, 'palette.accent', 0.25, name: 'Scan line'),
        ];

        foreach ($d['back'] as $i => [$action, $label]) {
            $x = 7.5 + 13 * $i;
            $elements[] = self::shape("back-ring-$i", $x - 3.6, 64.6, 7.2, 7.2, 'transparent', 'circle', 'palette.accent', 0.4, name: $label.' ring');
            $elements[] = str_starts_with($action, 'net:')
                ? self::social("back-action-$i", substr($action, 4), $x - 2, 66.2, 4, $label)
                : self::icon("back-action-$i", $action, $x - 2, 66.2, 4, 'palette.accent', 1.8, $label.' icon');
            $elements[] = self::text("back-label-$i", $label, $x - 6.5, 72.6, 13, 5.4, $body, 600, 'palette.text', ['name' => $label.' label']);
            if ($i > 0) {
                $elements[] = self::vline("back-sep-$i", 14 + 13 * ($i - 1), 65, 9, 'palette.accent', 0.2);
            }
        }

        array_push($elements,
            self::line('back-footer-left', 2.5, 79.6, 5, 'palette.accent', 0.25, name: 'Footer line'),
            self::text('back-footer', $d['footer'], 8, 78.1, self::W - 16, 8, $heading === 'Bebas Neue' ? $body : $heading, $heading === 'Bebas Neue' ? 500 : $d['weight'], 'palette.accent', ['name' => 'Footer', 'fontSize' => in_array($heading, ['Bebas Neue', 'Cinzel', 'Space Grotesk', 'Playfair Display'], true) ? 5.6 : 8.5]),
            self::line('back-footer-right', self::W - 7.5, 79.6, 5, 'palette.accent', 0.25, name: 'Footer line'),
        );

        return [
            'background' => ['type' => 'gradient', 'angle' => 90, 'stops' => [
                ['offset' => 0, 'color' => 'palette.secondary'],
                ['offset' => 0.45, 'color' => 'palette.background'],
                ['offset' => 1, 'color' => 'palette.primary'],
            ]],
            'elements' => $elements,
        ];
    }

    /** "—— SUBTITLE ——" row. */
    private static function subtitle(string $side, string $text, float $y, string $font): array
    {
        return [
            self::line("$side-sub-left", 4, $y + 0.85, 7, 'palette.accent', 0.3, name: 'Subtitle line'),
            self::text("$side-subtitle", $text, 11.5, $y, self::W - 23, 6.4, $font, 700, 'palette.accent', ['name' => 'Subtitle', 'textTransform' => 'uppercase', 'letterSpacing' => 160]),
            self::line("$side-sub-right", self::W - 11, $y + 0.85, 7, 'palette.accent', 0.3, name: 'Subtitle line'),
        ];
    }

    // ------------------------------------------------------------------ element helpers

    private static function base(string $id, string $type, string $name, float $x, float $y, float $w, float $h): array
    {
        return ['id' => $id, 'type' => $type, 'name' => $name, 'x' => round($x, 2), 'y' => round($y, 2), 'width' => round($w, 2), 'height' => round($h, 2), 'rotation' => 0, 'opacity' => 1, 'locked' => false, 'hidden' => false];
    }

    private static function text(string $id, string $text, float $x, float $y, float $w, float $size, string $font, int $weight, string $color, array $opts = []): array
    {
        $size = $opts['fontSize'] ?? $size;

        return self::base($id, $size >= 10 ? 'heading' : 'text', $opts['name'] ?? 'Text', $x, $y, $w, $size * 0.352778 * 1.2) + [
            'text' => $text, 'fontFamily' => $font, 'fontSize' => $size, 'fontWeight' => $weight, 'fontStyle' => 'normal',
            'color' => $color, 'align' => 'center', 'letterSpacing' => $opts['letterSpacing'] ?? 0, 'lineHeight' => 1.2,
            'textTransform' => $opts['textTransform'] ?? 'none',
        ];
    }

    private static function shape(string $id, float $x, float $y, float $w, float $h, string $fill, string $shape = 'rect', ?string $stroke = null, float $strokeWidth = 0, float $radius = 0, string $name = 'Shape', float $opacity = 1): array
    {
        return array_merge(self::base($id, 'shape', $name, $x, $y, $w, $h), [
            'opacity' => $opacity, 'shape' => $shape, 'fill' => $fill, 'stroke' => $stroke, 'strokeWidth' => $strokeWidth, 'radius' => $radius,
        ]);
    }

    private static function line(string $id, float $x, float $y, float $w, string $color, float $sw, string $name = 'Divider'): array
    {
        return self::base($id, 'line', $name, $x, $y - 0.5, $w, 1) + ['stroke' => $color, 'strokeWidth' => $sw, 'dash' => 'solid'];
    }

    /** Vertical divider centred on $x, from $y down $length mm. */
    private static function vline(string $id, float $x, float $y, float $length, string $color, float $sw): array
    {
        return array_merge(self::line($id, $x - $length / 2, $y + $length / 2, $length, $color, $sw, 'Separator'), ['rotation' => 90, 'opacity' => 0.6]);
    }

    private static function icon(string $id, string $icon, float $x, float $y, float $size, string $color, float $strokeWidth, string $name): array
    {
        return self::base($id, 'icon', $name, $x, $y, $size, $size) + ['icon' => $icon, 'color' => $color, 'strokeWidth' => $strokeWidth];
    }

    private static function social(string $id, string $network, float $x, float $y, float $size, string $name): array
    {
        return self::base($id, 'social', $name, $x, $y, $size, $size) + ['network' => $network, 'color' => 'palette.accent', 'style' => 'plain'];
    }

    private static function image(string $id, float $x, float $y, float $w, float $h): array
    {
        return self::base($id, 'logo', 'Logo', $x, $y, $w, $h) + ['src' => '{{logo}}', 'fit' => 'contain', 'mask' => 'none', 'border' => 0, 'placeholderColor' => 'palette.accent'];
    }

    private static function qr(string $id, float $x, float $y, float $size): array
    {
        return self::base($id, 'qr', 'QR code', $x, $y, $size, $size) + ['data' => '{{profile_url}}', 'color' => '#111111', 'background' => '#ffffff', 'margin' => 0.5];
    }
}
